"""Generate the differential test-case file used by both implementations."""
import os

OUT = '/tmp/h/case_body.py'

HEADER = '''# -*- coding: utf-8 -*-
import io
import sys
import contextlib
import warnings

from icecream import ic, argumentToString
import icecream as _icmod
from icecream.icecream import (
    IceCreamDebugger, colorize, stderrPrint, colorizedStderrPrint,
    isLiteral, callOrValue, prefixLines, prefixFirstLineIndentRemaining,
    formatPair, DEFAULT_PREFIX, DEFAULT_LINE_WRAP_WIDTH,
    DEFAULT_CONTEXT_DELIMITER, NO_SOURCE_AVAILABLE_WARNING_MESSAGE,
)

RESULTS = []


def rec(label, value):
    RESULTS.append((label, value))


@contextlib.contextmanager
def capErr():
    buf = io.StringIO()
    with contextlib.redirect_stderr(buf):
        yield buf


class Klass:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def __repr__(self):
        return 'Klass(a=%r, b=%r)' % (self.a, self.b)


class EmptyRepr:
    def __repr__(self):
        return ''


class OneCharRepr:
    def __repr__(self):
        return 'x'


class QuoteRepr:
    def __repr__(self):
        return "'"


class MultilineRepr:
    def __repr__(self):
        return 'line1\\nline2\\nline3'


def noop(*a, **k):
    pass


def main():
    pass
'''

FOOTER = '''

if __name__ == '__main__':
    run()
    out = []
    for label, value in RESULTS:
        out.append('### %s\\n%r' % (label, value))
    sys.stdout.write('\\n'.join(out) + '\\n')
'''


def main():
    with open('/tmp/h/cases_body.txt') as f:
        body = f.read()
    lines = ['def run():']
    for ln in body.splitlines():
        lines.append('    ' + ln if ln.strip() else '')
    src = HEADER + '\n' + '\n'.join(lines) + FOOTER
    with open(OUT, 'w') as f:
        f.write(src)
    print('wrote', OUT, len(src.splitlines()), 'lines')


main()

